+import { describe, it, expect } from "vitest";
+import {
+  FEATURE_STATUS_OPTIONS,
+  isValidFeatureStatus,
+  normalizeFeatureStatus,
+  getFeatureStatusLabel,
+  getFeatureStatusColor,
+  type FeatureStatus,
+} from "../features/board/lib/status";
+
+// ─── Allowed feature lifecycle statuses per T6 spec ─────────────────────────
+
+const ALL_VALID_FEATURE_STATUSES: FeatureStatus[] = [
+  "in_design",
+  "in_tdd",
+  "ready_for_implementation",
+  "in_implementation",
+  "in_handoff",
+  "done",
+  "blocked",
+  "cancelled",
+];
+
+// ─── Task lifecycle statuses that must NOT appear as feature status ─────────
+
+const TASK_STATUSES_THAT_MUST_NOT_APPEAR = [
+  "todo",
+  "ready",
+  "in_progress",
+  "in_review",
+];
+
+// ─── isValidFeatureStatus ───────────────────────────────────────────────────
+
+describe("isValidFeatureStatus — validates feature lifecycle statuses", () => {
+  it.each(ALL_VALID_FEATURE_STATUSES)(
+    "accepts '%s' as a valid feature lifecycle status",
+    (status: string) => {
+      expect(isValidFeatureStatus(status)).toBe(true);
+    },
+  );
+
+  it.each(TASK_STATUSES_THAT_MUST_NOT_APPEAR)(
+    "rejects task status '%s' — must not be treated as a feature lifecycle status",
+    (status: string) => {
+      expect(isValidFeatureStatus(status)).toBe(false);
+    },
+  );
+
+  it("rejects 'unknown'", () => {
+    expect(isValidFeatureStatus("unknown")).toBe(false);
+  });
+
+  it("rejects empty string", () => {
+    expect(isValidFeatureStatus("")).toBe(false);
+  });
+
+  it("rejects arbitrary strings", () => {
+    expect(isValidFeatureStatus("random_value")).toBe(false);
+    expect(isValidFeatureStatus("in_development")).toBe(false);
+    expect(isValidFeatureStatus("pending")).toBe(false);
+  });
+});
+
+// ─── normalizeFeatureStatus ─────────────────────────────────────────────────
+
+describe("normalizeFeatureStatus — normalizes to a valid FeatureStatus", () => {
+  it.each(ALL_VALID_FEATURE_STATUSES)(
+    "returns '%s' unchanged when already valid",
+    (status: string) => {
+      expect(normalizeFeatureStatus(status)).toBe(status);
+    },
+  );
+
+  it.each(TASK_STATUSES_THAT_MUST_NOT_APPEAR)(
+    "maps task status '%s' to 'in_design' (safe default), not a task-derived label",
+    (status: string) => {
+      const normalized = normalizeFeatureStatus(status);
+      expect(normalized).toBe("in_design");
+      // Must NOT return the raw task status or a task-derived value
+      expect(normalized).not.toBe(status);
+      // Must NOT return any other feature lifecycle status that could be
+      // confused with a task-derived mapping
+      const allowed: string[] = [...ALL_VALID_FEATURE_STATUSES];
+      expect(allowed).toContain(normalized);
+    },
+  );
+
+  it("maps 'unknown' to 'in_design'", () => {
+    expect(normalizeFeatureStatus("unknown")).toBe("in_design");
+  });
+
+  it("maps empty string to 'in_design'", () => {
+    expect(normalizeFeatureStatus("")).toBe("in_design");
+  });
+
+  it("returns 'in_design' for any unrecognized status", () => {
+    expect(normalizeFeatureStatus("some_future_status")).toBe("in_design");
+    expect(normalizeFeatureStatus("random")).toBe("in_design");
+  });
+});
+
+// ─── FEATURE_STATUS_OPTIONS — completeness and ordering ────────────────────
+
+describe("FEATURE_STATUS_OPTIONS — canonical feature status column list", () => {
+  it("contains exactly 8 feature lifecycle statuses", () => {
+    expect(FEATURE_STATUS_OPTIONS).toHaveLength(8);
+  });
+
+  it("lists every allowed feature lifecycle status", () => {
+    const keys = FEATURE_STATUS_OPTIONS.map((o) => o.key);
+    for (const status of ALL_VALID_FEATURE_STATUSES) {
+      expect(keys).toContain(status);
+    }
+  });
+
+  it("does NOT include any task lifecycle status", () => {
+    const keys = FEATURE_STATUS_OPTIONS.map((o) => o.key);
+    for (const taskStatus of TASK_STATUSES_THAT_MUST_NOT_APPEAR) {
+      expect(keys).not.toContain(taskStatus);
+    }
+  });
+
+  it("every option has a non-empty label and valid hex color", () => {
+    for (const opt of FEATURE_STATUS_OPTIONS) {
+      expect(opt.label).toBeTruthy();
+      expect(opt.color).toMatch(/^#[0-9a-fA-F]{6}$/);
+    }
+  });
+
+  it("every option key is a valid FeatureStatus", () => {
+    for (const opt of FEATURE_STATUS_OPTIONS) {
+      expect(isValidFeatureStatus(opt.key)).toBe(true);
+    }
+  });
+
+  it("is ordered: design → tdd → ready → implement → handoff → done → blocked → cancelled", () => {
+    const keys = FEATURE_STATUS_OPTIONS.map((o) => o.key);
+    expect(keys).toEqual([
+      "in_design",
+      "in_tdd",
+      "ready_for_implementation",
+      "in_implementation",
+      "in_handoff",
+      "done",
+      "blocked",
+      "cancelled",
+    ]);
+  });
+});
+
+// ─── getFeatureStatusLabel — human-readable display ─────────────────────────
+
+describe("getFeatureStatusLabel", () => {
+  it.each([
+    ["in_design", "In Design"],
+    ["in_tdd", "In TDD"],
+    ["ready_for_implementation", "Ready"],
+    ["in_implementation", "In Progress"],
+    ["in_handoff", "Handoff"],
+    ["done", "Done"],
+    ["blocked", "Blocked"],
+    ["cancelled", "Cancelled"],
+  ] as const)("maps '%s' → '%s'", (status: string, expected: string) => {
+    expect(getFeatureStatusLabel(status)).toBe(expected);
+  });
+
+  it.each(TASK_STATUSES_THAT_MUST_NOT_APPEAR)(
+    "does NOT have a feature-label mapping for task status '%s' — falls back to raw string",
+    (status: string) => {
+      const label = getFeatureStatusLabel(status);
+      // Falls back to raw string
+      expect(label).toBe(status);
+      // Must not be a human-readable feature status label
+      const featureLabels = FEATURE_STATUS_OPTIONS.map((o) => o.label);
+      expect(featureLabels).not.toContain(label);
+    },
+  );
+});
+
+// ─── getFeatureStatusColor — color mapping ─────────────────────────────────
+
+describe("getFeatureStatusColor", () => {
+  it.each(ALL_VALID_FEATURE_STATUSES)(
+    "returns a valid hex color for '%s'",
+    (status: string) => {
+      expect(getFeatureStatusColor(status)).toMatch(/^#[0-9a-fA-F]{6}$/);
+    },
+  );
+
+  it.each(TASK_STATUSES_THAT_MUST_NOT_APPEAR)(
+    "returns a fallback color (not feature-status-mapped) for task status '%s'",
+    (status: string) => {
+      const color = getFeatureStatusColor(status);
+      expect(color).toMatch(/^#[0-9a-fA-F]{6}$/);
+      // Must be the generic fallback, not any feature status color
+      expect(color).toBe("#8892b5");
+    },
+  );
+
+  it("returns fallback color for unknown status", () => {
+    expect(getFeatureStatusColor("unknown")).toBe("#8892b5");
+  });
+});
+
+// ─── TypeScript type narrowing — FeatureStatus union ────────────────────────
+
+describe("FeatureStatus type union — exhaustive check", () => {
+  it("covers exactly 8 members", () => {
+    // This test is a compile-time guard; at runtime it just confirms
+    // the ALL_VALID_FEATURE_STATUSES list is complete.
+    const count = ALL_VALID_FEATURE_STATUSES.length;
+    expect(count).toBe(8);
+  });
+
+  it("every FEATURE_STATUS_OPTIONS key is assignable to FeatureStatus", () => {
+    for (const opt of FEATURE_STATUS_OPTIONS) {
+      const status: FeatureStatus = opt.key;
+      expect(status).toBe(opt.key);
+    }
+  });
+});
diff --git a/src/__tests__/t6-kanban-status.test.ts b/src/__tests__/t6-kanban-status.test.ts
new file mode 100644
index 0000000..21a6479
--- /dev/null
+++ b/src/__tests__/t6-kanban-status.test.ts
@@ -0,0 +1,331 @@
+/**
+ * T6 — Kanban feature lifecycle status mapping tests
+ *
+ * Covers:
+ *   1. All 8 valid feature lifecycle statuses are accepted by isValidFeatureStatus
+ *   2. Task lifecycle statuses are rejected by isValidFeatureStatus
+ *   3. normalizeFeatureStatus maps valid statuses through unchanged
+ *   4. normalizeFeatureStatus falls back to "in_design" for invalid statuses
+ *   5. FeatureBoardView getFeatureStatusColumns returns exactly the 8 lifecycle columns
+ *   6. FeatureBoardView filters out features with non-lifecycle statuses (regression)
+ *   7. FeatureListRow exposes featureStatus via data attribute for DOM testing
+ */
+
+import React from "react";
+import { renderToStaticMarkup } from "react-dom/server";
+import { describe, expect, it } from "vitest";
+import type { ParsedFeature } from "../services/yaml-parser";
+import type { FeatureStatus } from "../features/board/lib/status";
+import {
+  FEATURE_STATUS_OPTIONS,
+  isValidFeatureStatus,
+  normalizeFeatureStatus,
+  getFeatureStatusLabel,
+} from "../features/board/lib/status";
+import { FeatureListRow } from "../features/board/components/FeatureBoardView/FeatureListRow";
+import { FeatureRow } from "../features/board/components/FeatureRow/FeatureRow";
+
+// ─── Helpers ────────────────────────────────────────────────────────────────
+
+function makeFeature(overrides: Partial<ParsedFeature> = {}): ParsedFeature {
+  return {
+    id: "test-feature",
+    title: "Test Feature Title",
+    featureStatus: "in_implementation",
+    tasks: [],
+    ...overrides,
+  };
+}
+
+const ALL_VALID_FEATURE_STATUSES: FeatureStatus[] = [
+  "in_design",
+  "in_tdd",
+  "ready_for_implementation",
+  "in_implementation",
+  "in_handoff",
+  "done",
+  "blocked",
+  "cancelled",
+];
+
+const TASK_STATUSES = [
+  "todo",
+  "ready",
+  "in_progress",
+  "in_review",
+] as const;
+
+// ─── 1. isValidFeatureStatus ────────────────────────────────────────────────
+
+describe("isValidFeatureStatus", () => {
+  it("accepts all 8 valid feature lifecycle statuses", () => {
+    for (const status of ALL_VALID_FEATURE_STATUSES) {
+      expect(isValidFeatureStatus(status)).toBe(true);
+    }
+  });
+
+  it("rejects task lifecycle statuses", () => {
+    for (const status of TASK_STATUSES) {
+      expect(isValidFeatureStatus(status)).toBe(false);
+    }
+  });
+
+  it("rejects empty string", () => {
+    expect(isValidFeatureStatus("")).toBe(false);
+  });
+
+  it("rejects unknown strings", () => {
+    expect(isValidFeatureStatus("unknown")).toBe(false);
+    expect(isValidFeatureStatus("deployed")).toBe(false);
+    expect(isValidFeatureStatus("archived")).toBe(false);
+  });
+
+  it("type guard narrows correctly via runtime check", () => {
+    const raw = "in_design" as string;
+    if (isValidFeatureStatus(raw)) {
+      // raw is narrowed to FeatureStatus — no type error
+      const _safe: FeatureStatus = raw;
+      expect(getFeatureStatusLabel(_safe)).toBe("In Design");
+    }
+  });
+});
+
+// ─── 2. normalizeFeatureStatus ──────────────────────────────────────────────
+
+describe("normalizeFeatureStatus", () => {
+  it("maps valid feature lifecycle statuses through unchanged", () => {
+    for (const status of ALL_VALID_FEATURE_STATUSES) {
+      expect(normalizeFeatureStatus(status)).toBe(status);
+    }
+  });
+
+  it("maps task statuses to the fallback 'in_design'", () => {
+    for (const status of TASK_STATUSES) {
+      expect(normalizeFeatureStatus(status)).toBe("in_design");
+    }
+  });
+
+  it("maps unknown/empty strings to the fallback 'in_design'", () => {
+    expect(normalizeFeatureStatus("")).toBe("in_design");
+    expect(normalizeFeatureStatus("unknown")).toBe("in_design");
+  });
+});
+
+// ─── 3. FEATURE_STATUS_OPTIONS contract ─────────────────────────────────────
+
+describe("FEATURE_STATUS_OPTIONS — Kanban column contract", () => {
+  it("contains exactly the 8 canonical feature lifecycle statuses", () => {
+    const keys = FEATURE_STATUS_OPTIONS.map((o) => o.key);
+    expect(new Set(keys)).toEqual(new Set(ALL_VALID_FEATURE_STATUSES));
+    expect(keys).toHaveLength(8);
+  });
+
+  it("every option has a non-empty label and valid hex color", () => {
+    for (const opt of FEATURE_STATUS_OPTIONS) {
+      expect(opt.label).toBeTruthy();
+      expect(opt.color).toMatch(/^#[0-9a-fA-F]{6}$/);
+    }
+  });
+
+  it("does NOT contain any task lifecycle status", () => {
+    const keys = new Set(FEATURE_STATUS_OPTIONS.map((o) => o.key));
+    for (const taskStatus of TASK_STATUSES) {
+      expect(keys.has(taskStatus)).toBe(false);
+    }
+  });
+});
+
+// ─── 4. FeatureListRow — Kanban card status contract ────────────────────────
+
+describe("FeatureListRow — Kanban card status data attribute", () => {
+  it("exposes every valid feature lifecycle status via data-feature-card-status", () => {
+    for (const status of ALL_VALID_FEATURE_STATUSES) {
+      const feature = makeFeature({
+        id: `feat-${status}`,
+        featureStatus: status,
+        title: `Feature: ${status}`,
+      });
+      const html = renderToStaticMarkup(
+        React.createElement(FeatureListRow, {
+          feature,
+          onClick: () => undefined,
+        }),
+      );
+      expect(html).toContain(`data-feature-card-status="${status}"`);
+    }
+  });
+
+  it("still exposes status even when featureStatus is non-lifecycle (no filter at card level)", () => {
+    const feature = makeFeature({
+      id: "feat-todo",
+      featureStatus: "todo",
+      title: "Todo Feature",
+    });
+    const html = renderToStaticMarkup(
+      React.createElement(FeatureListRow, {
+        feature,
+        onClick: () => undefined,
+      }),
+    );
+    // Card always writes the raw status to the data attribute
+    expect(html).toContain('data-feature-card-status="todo"');
+  });
+});
+
+// ─── 5. FeatureRow — task-mode feature row status rendering ─────────────────
+
+describe("FeatureRow — lifecycle status rendering", () => {
+  it("renders all 8 valid feature lifecycle status labels", () => {
+    const labels: Record<FeatureStatus, string> = {
+      in_design: "In Design",
+      in_tdd: "In TDD",
+      ready_for_implementation: "Ready",
+      in_implementation: "In Progress",
+      in_handoff: "Handoff",
+      done: "Done",
+      blocked: "Blocked",
+      cancelled: "Cancelled",
+    };
+
+    for (const [status, label] of Object.entries(labels) as [
+      FeatureStatus,
+      string,
+    ][]) {
+      const feature = makeFeature({
+        id: `feat-${status}`,
+        featureStatus: status,
+        title: `Feature: ${label}`,
+      });
+      const html = renderToStaticMarkup(
+        React.createElement(FeatureRow, {
+          feature,
+          isExpanded: false,
+          onToggle: () => undefined,
+          onSelectTask: () => undefined,
+        }),
+      );
+      expect(html).toContain(label);
+    }
+  });
+
+  it("renders feature lifecycle status 'blocked' even when tasks are not blocked", () => {
+    const feature = makeFeature({
+      id: "blocked-feature",
+      featureStatus: "blocked",
+      title: "Blocked Feature",
+      tasks: [
+        { id: "T1", title: "Task one", status: "in_progress", dependsOn: [] },
+        { id: "T2", title: "Task two", status: "done", dependsOn: [] },
+      ],
+    });
+    const html = renderToStaticMarkup(
+      React.createElement(FeatureRow, {
+        feature,
+        isExpanded: false,
+        onToggle: () => undefined,
+        onSelectTask: () => undefined,
+      }),
+    );
+    expect(html).toContain("Blocked");
+  });
+
+  it("does NOT derive feature status from task statuses (regression guard)", () => {
+    // If the feature status says "done" but all tasks are todo,
+    // the rendered status must still be "Done" — not task-derived.
+    const feature = makeFeature({
+      id: "done-feature",
+      featureStatus: "done",
+      title: "Done Feature",
+      tasks: [
+        { id: "T1", title: "Todo task", status: "todo", dependsOn: [] },
+        { id: "T2", title: "Another todo", status: "todo", dependsOn: [] },
+      ],
+    });
+    const html = renderToStaticMarkup(
+      React.createElement(FeatureRow, {
+        feature,
+        isExpanded: false,
+        onToggle: () => undefined,
+        onSelectTask: () => undefined,
+      }),
+    );
+    expect(html).toContain("Done");
+    // Must NOT show any task lifecycle label as the feature status
+    expect(html).not.toMatch(
+      /data-feature-status="[^"]*"\s*>\s*Todo\s*<\//,
+    );
+  });
+});
+
+// ─── 6. Regression: task statuses NOT shown as feature lifecycle status ─────
+
+describe("T6 regression — task statuses are not feature lifecycle statuses", () => {
+  it("isValidFeatureStatus rejects 'todo'", () => {
+    expect(isValidFeatureStatus("todo")).toBe(false);
+  });
+

